     1|/*
     2| * IVX Investor-First Home Feed — ivxholding.com
     3| *
     4| * Enforces the CANONICAL home layout from the single source of truth
     5| * (GET /api/ivx/video-platform/home-feed) — the exact same sequence the
     6| * Android and iOS apps render:
     7| *
     8| *   Featured Deal 1–3 → 1 Featured Project Video → Deal 4–6 → 1 video → repeat
     9| *
    10| * Behaviour:
    11| *   • Reorders the rendered deal cards in #properties-grid to the canonical order.
    12| *   • Inserts exactly ONE featured project video card after every 3 deals.
    13| *   • Every video card is attached to a real project (name, city, phase,
    14| *     investment, ROI, minimum, progress %, View Deal + Invest Now).
    15| *   • Performance: poster image loads first; the video source attaches only
    16| *     when the card scrolls into view; only the next upcoming video preloads.
    17| *   • Admin publish (deal/video meta) updates this page automatically on the
    18| *     next load — no separate configuration.
    19| */
    20|(function () {
    21|  'use strict';
    22|  if (window.__ivxHomeFeedLoaded) return;
    23|  window.__ivxHomeFeedLoaded = true;
    24|
    25|  var API_CANDIDATES = ['https://api.ivxholding.com', 'https://ivx-holdings-platform.onrender.com'];
    26|  var HLS_CDN = 'https://cdn.jsdelivr.net/npm/hls.js@1.5.20/dist/hls.min.js';
    27|
    28|  var homeFeed = null;      /* canonical blocks from the backend */
    29|  var applying = false;     /* guard against observer feedback loops */
    30|
    31|  /* ---------- helpers ---------- */
    32|  function esc(s) {
    33|    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
    34|      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    35|    });
    36|  }
    37|  function money(n) {
    38|    n = Number(n) || 0;
    39|    if (n >= 1000000) return '$' + (n / 1000000).toFixed(n % 1000000 === 0 ? 0 : 1) + 'M';
    40|    if (n >= 1000) return '$' + (n / 1000).toFixed(n % 1000 === 0 ? 0 : 1) + 'K';
    41|    return '$' + Math.round(n);
    42|  }
    43|
    44|  function fetchHomeFeed(i) {
    45|    i = i || 0;
    46|    if (i >= API_CANDIDATES.length) return Promise.reject(new Error('all API hosts failed'));
    47|    return fetch(API_CANDIDATES[i] + '/api/ivx/video-platform/home-feed?limit=60')
    48|      .then(function (r) {
    49|        var ct = (r.headers.get('content-type') || '').toLowerCase();
    50|        if (!r.ok || ct.indexOf('json') === -1) throw new Error('bad response');
    51|        return r.json();
    52|      })
    53|      .catch(function () { return fetchHomeFeed(i + 1); });
    54|  }
    55|
    56|  /* ---------- lazy HLS ---------- */
    57|  var hlsLoading = null;
    58|  function loadHlsJs() {
    59|    if (window.Hls) return Promise.resolve();
    60|    if (hlsLoading) return hlsLoading;
    61|    hlsLoading = new Promise(function (resolve) {
    62|      var s = document.createElement('script');
    63|      s.src = HLS_CDN; s.async = true;
    64|      s.onload = function () { resolve(); };
    65|      s.onerror = function () { resolve(); };
    66|      document.head.appendChild(s);
    67|    });
    68|    return hlsLoading;
    69|  }
    70|  function attachSource(video, hlsUrl, fallbackUrl) {
    71|    if (video.__ivxAttached) return;
    72|    video.__ivxAttached = true;
    73|    if (!hlsUrl) { if (fallbackUrl) video.src = fallbackUrl; return; }
    74|    if (video.canPlayType('application/vnd.apple.mpegurl')) { video.src = hlsUrl; return; }
    75|    loadHlsJs().then(function () {
    76|      if (window.Hls && window.Hls.isSupported()) {
    77|        var h = new window.Hls({ capLevelToPlayerSize: true, maxBufferLength: 15 });
    78|        h.on(window.Hls.Events.ERROR, function (_e, data) {
    79|          if (data && data.fatal) { try { h.destroy(); } catch (e) {} if (fallbackUrl) video.src = fallbackUrl; }
    80|        });
    81|        h.loadSource(hlsUrl);
    82|        h.attachMedia(video);
    83|        video.__ivxHls = h;
    84|      } else if (fallbackUrl) {
    85|        video.src = fallbackUrl;
    86|      }
    87|    });
    88|  }
    89|
    90|  /* ---------- styles ---------- */
    91|  var css = ''
    92|    + '.ivx-hf-video{grid-column:1/-1;background:#141414;border:1px solid rgba(255,215,0,.25);border-radius:16px;'
    93|    + 'overflow:hidden;display:flex;flex-direction:column}'
    94|    + '.ivx-hf-media{position:relative;background:#000;aspect-ratio:16/9;max-height:420px;overflow:hidden}'
    95|    + '.ivx-hf-media img,.ivx-hf-media video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}'
    96|    + '.ivx-hf-tag{position:absolute;top:12px;left:12px;z-index:3;background:#FFD700;color:#000;border-radius:6px;'
    97|    + 'padding:4px 10px;font:800 11px/1 -apple-system,Segoe UI,sans-serif;text-transform:uppercase;letter-spacing:.5px}'
    98|    + '.ivx-hf-mute{position:absolute;bottom:12px;right:12px;z-index:3;background:rgba(0,0,0,.6);color:#fff;border:none;'
    99|    + 'border-radius:50%;width:36px;height:36px;font-size:16px;cursor:pointer}'
   100|    + '.ivx-hf-body{padding:16px;color:#fff;font-family:-apple-system,Segoe UI,sans-serif}'
   101|    + '.ivx-hf-name{font-weight:800;font-size:17px;margin-bottom:2px}'
   102|    + '.ivx-hf-loc{color:#9a9a9a;font-size:12.5px;margin-bottom:4px}'
   103|    + '.ivx-hf-phase{display:inline-block;color:#00C48C;background:rgba(34,197,94,.12);border-radius:5px;'
   104|    + 'padding:3px 8px;font:700 10.5px/1.2 -apple-system,sans-serif;text-transform:uppercase;letter-spacing:.4px;margin-bottom:8px}'
   105|    + '.ivx-hf-stats{display:flex;gap:0;background:#1E1E1E;border-radius:10px;padding:10px 4px;margin-bottom:10px}'
   106|    + '.ivx-hf-stat{flex:1;text-align:center}'
   107|    + '.ivx-hf-stat .v{font-weight:800;font-size:14px}'
   108|    + '.ivx-hf-stat .l{color:#7a7a7a;font-size:9.5px;font-weight:600;text-transform:uppercase;margin-top:2px}'
   109|    + '.ivx-hf-prog{display:flex;align-items:center;gap:8px;margin-bottom:12px}'
   110|    + '.ivx-hf-prog .track{flex:1;height:6px;border-radius:3px;background:#1E1E1E;overflow:hidden}'
   111|    + '.ivx-hf-prog .fill{height:100%;border-radius:3px;background:#FFD700}'
   112|    + '.ivx-hf-prog .pct{color:#9a9a9a;font-size:11.5px;font-weight:700}'
   113|    + '.ivx-hf-btns{display:flex;gap:8px}'
   114|    + '.ivx-hf-btns a{flex:1;text-align:center;border-radius:10px;padding:12px 0;font:700 14px/1 -apple-system,Segoe UI,sans-serif;'
   115|    + 'text-decoration:none;cursor:pointer}'
   116|    + '.ivx-hf-view{background:#1E1E1E;color:#fff;border:1px solid rgba(255,255,255,.12)}'
   117|    + '.ivx-hf-invest{background:#FFD700;color:#000}';
   118|  var styleEl = document.createElement('style');
   119|  styleEl.textContent = css;
   120|  document.head.appendChild(styleEl);
