   122|  /* ---------- featured project video card ---------- */
   123|  function buildVideoCard(v) {
   124|    var deal = v.deal || {};
   125|    var card = document.createElement('div');
   126|    card.className = 'ivx-hf-video';
   127|    card.setAttribute('data-ivx-home-feed-video', v.id);
   128|
   129|    var poster = v.poster_url || v.thumbnail_url || v.preview_blur_url || '';
   130|    var statBits = '';
   131|    if (deal.investment_amount) statBits += '<div class="ivx-hf-stat"><div class="v">' + money(deal.investment_amount) + '</div><div class="l">Investment</div></div>';
   132|    if (deal.expected_roi) statBits += '<div class="ivx-hf-stat"><div class="v" style="color:#00C48C">' + esc(deal.expected_roi) + '%</div><div class="l">ROI</div></div>';
   133|    if (deal.min_investment) statBits += '<div class="ivx-hf-stat"><div class="v">' + money(deal.min_investment) + '</div><div class="l">Minimum</div></div>';
   134|    var progressRow = '';
   135|    if (deal.progress_percent != null) {
   136|      var pct = Math.min(100, Math.max(0, Number(deal.progress_percent) || 0));
   137|      progressRow = '<div class="ivx-hf-prog"><div class="track"><div class="fill" style="width:' + pct + '%"></div></div>'
   138|        + '<span class="pct">' + pct + '%</span></div>';
   139|    }
   140|    var dealUrl = deal.url || 'https://ivxholding.com/#deals';
   141|
   142|    card.innerHTML = ''
   143|      + '<div class="ivx-hf-media">'
   144|      + '  <span class="ivx-hf-tag">Featured Project Video</span>'
   145|      + (poster ? '<img src="' + esc(poster) + '" alt="' + esc(deal.name || v.title || '') + '" loading="lazy"/>' : '')
   146|      + '  <video playsinline muted loop preload="none"' + (poster ? ' poster="' + esc(poster) + '"' : '') + ' style="opacity:0"></video>'
   147|      + '  <button class="ivx-hf-mute" aria-label="Unmute">&#128263;</button>'
   148|      + '</div>'
   149|      + '<div class="ivx-hf-body">'
   150|      + '  <div class="ivx-hf-name">' + esc(deal.name || v.title || 'IVX Project') + '</div>'
   151|      + (deal.city ? '<div class="ivx-hf-loc">&#128205; ' + esc(deal.city) + '</div>' : '')
   152|      + (deal.phase ? '<span class="ivx-hf-phase">' + esc(deal.phase) + '</span>' : '')
   153|      + (statBits ? '<div class="ivx-hf-stats">' + statBits + '</div>' : '')
   154|      + progressRow
   155|      + '  <div class="ivx-hf-btns">'
   156|      + '    <a class="ivx-hf-view" href="' + esc(dealUrl) + '">View Deal</a>'
   157|      + '    <a class="ivx-hf-invest" href="https://chat.ivxholding.com/investor">Invest Now</a>'
   158|      + '  </div>'
   159|      + '</div>';
   160|
   161|    var vid = card.querySelector('video');
   162|    var img = card.querySelector('.ivx-hf-media img');
   163|    var muteBtn = card.querySelector('.ivx-hf-mute');
   164|    muteBtn.addEventListener('click', function () {
   165|      vid.muted = !vid.muted;
   166|      muteBtn.innerHTML = vid.muted ? '&#128263;' : '&#128266;';
   167|    });
   168|
   169|    /* Lazy playback: attach the source ONLY when visible; images load first. */
   170|    card.__ivxActivate = function () {
   171|      attachSource(vid, v.hls_url, v.video_url);
   172|      vid.play().then(function () {
   173|        vid.style.opacity = '1';
   174|        if (img) img.style.opacity = '0';
   175|      }).catch(function () {});
   176|    };
   177|    card.__ivxDeactivate = function () { try { vid.pause(); } catch (e) {} };
   178|    card.__ivxPreload = function () {
   179|      /* preload the NEXT featured video only — metadata, no full download */
   180|      if (!vid.__ivxAttached) { vid.preload = 'metadata'; attachSource(vid, v.hls_url, v.video_url); }
   181|    };
   182|    return card;
   183|  }
   184|
   185|  var videoIO = null;
   186|  function observeVideoCards(grid) {
   187|    if (!videoIO) {
   188|      videoIO = new IntersectionObserver(function (entries) {
   189|        entries.forEach(function (entry) {
   190|          var card = entry.target;
   191|          if (entry.isIntersecting && entry.intersectionRatio >= 0.35) {
   192|            if (card.__ivxActivate) card.__ivxActivate();
   193|            /* preload only the next upcoming video card */
   194|            var all = Array.prototype.slice.call(document.querySelectorAll('[data-ivx-home-feed-video]'));
   195|            var idx = all.indexOf(card);
   196|            if (idx >= 0 && all[idx + 1] && all[idx + 1].__ivxPreload) all[idx + 1].__ivxPreload();
   197|          } else if (!entry.isIntersecting && card.__ivxDeactivate) {
   198|            card.__ivxDeactivate();
   199|          }
   200|        });

