   154|  /* ---------- styles ---------- */
   155|  var css = ''
   156|    + '#ivxReelsBtn{position:fixed;left:16px;bottom:18px;z-index:99990;display:flex;align-items:center;gap:8px;'
   157|    + 'background:linear-gradient(135deg,#E6C200,#E6C200);color:#fff;border:none;border-radius:999px;padding:12px 20px;'
   158|    + 'font:600 15px/1 -apple-system,Segoe UI,sans-serif;box-shadow:0 6px 24px rgba(0,0,0,.35);cursor:pointer;transition:transform .15s}'
   159|    + '#ivxReelsBtn:active{transform:scale(.94)}'
   160|    + '#ivxReels{position:fixed;inset:0;z-index:99991;background:#000;display:none;flex-direction:column}'
   161|    + '#ivxReels.open{display:flex}'
   162|    + '.ivxr-top{position:absolute;top:0;left:0;right:0;z-index:30;padding:calc(10px + env(safe-area-inset-top)) 10px 10px;'
   163|    + 'background:linear-gradient(rgba(0,0,0,.65),transparent);display:flex;flex-direction:column;gap:8px}'
   164|    + '.ivxr-row{display:flex;align-items:center;gap:8px}'
   165|    + '.ivxr-tabs{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;flex:1}'
   166|    + '.ivxr-tabs::-webkit-scrollbar{display:none}'
   167|    + '.ivxr-tab{flex:0 0 auto;background:rgba(255,255,255,.14);color:#fff;border:none;border-radius:999px;padding:7px 14px;'
   168|    + 'font:600 13px/1 -apple-system,Segoe UI,sans-serif;cursor:pointer}'
   169|    + '.ivxr-tab.on{background:#fff;color:#000}'
   170|    + '.ivxr-ico{background:rgba(255,255,255,.14);color:#fff;border:none;border-radius:50%;width:38px;height:38px;'
